package com.bank.scheduler.service;

import com.bank.scheduler.model.Interval;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.logging.Logger;

// Returns true if any two booking windows clash (overlap).
public class BookingConflictChecker {
    private static final Logger log = Logger.getLogger(BookingConflictChecker.class.getName());

    public boolean hasConflict(List<Interval> bookings) {
        if (bookings == null || bookings.size() < 2) {
            return false;
        }
        List<Interval> sorted = new ArrayList<>(bookings);
        sorted.sort(Comparator.comparingInt(Interval::getStart));

        for (int i = 1; i < sorted.size(); i++) {
            Interval prev = sorted.get(i - 1);
            Interval cur = sorted.get(i);
            // Touching (cur.start == prev.end) is allowed → strict less-than.
            if (cur.getStart() < prev.getEnd()) {
                log.fine(() -> "Conflict: " + cur + " starts before " + prev + " ends");
                log.info(() -> "Booking conflict detected = true");
                return true;
            }
        }
        log.info(() -> "Booking conflict detected = false");
        return false;
    }
}
